CREATE TABLE members (id INTEGER, name TEXT);
CREATE TABLE workouts (id INTEGER, member_id INTEGER, minutes INTEGER);
INSERT INTO members VALUES (1,'Sam'),(2,'Ravi');
INSERT INTO workouts VALUES
  (1,1,30),(2,1,45),(3,2,20);
SELECT members.name, SUM(workouts.minutes) AS total_minutes
FROM members
JOIN workouts ON workouts.member_id = members.id
GROUP BY members.name
ORDER BY total_minutes DESC;

